import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(8))
G.add_edges_from([(2,6), (0,6), (4,7), (6,7), (3,7)])

for u in range(8):
    for v in range(u+1, 8):
        if G.degree(u) < 3 and G.degree(v) < 3 and not G.has_edge(u, v):
            G.add_edge(u, v)

if all(degree >= 3 for degree in G.degree()):
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
